import{_ as e,o as a,c as s,a2 as n}from"./chunks/framework.dWYrTn1b.js";const u=JSON.parse(`{"title":"Running the output","description":"What the compiler writes for a target, how to launch it, the launch arguments, and where a run's results go.","frontmatter":{"title":"Running the output","description":"What the compiler writes for a target, how to launch it, the launch arguments, and where a run's results go."},"headers":[],"relativePath":"guide/basics/running.md","filePath":"guide/basics/running.md"}`),i={name:"guide/basics/running.md"};function o(r,t,d,h,l,p){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="running-the-output" tabindex="-1">Running the output <a class="header-anchor" href="#running-the-output" aria-label="Permalink to &quot;Running the output&quot;">​</a></h1><p><code>--target</code> and <code>--output</code> turn a checked program into one directory that runs as it is.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mobiledsl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> robot.core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> robot.world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> robot.task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> robot.eval</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --library</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> parts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ros-gz-nav2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><h2 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to &quot;Targets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Target</th><th>For</th></tr></thead><tbody><tr><td><code>ros-gz-nav2</code></td><td>ROS 2 Jazzy, Gazebo Harmonic, <code>ros2_control</code>, Nav2</td></tr><tr><td><code>ros-mujoco-nav2</code></td><td>ROS 2 Jazzy, MuJoCo, <code>ros2_control</code>, Nav2</td></tr></tbody></table><p>Both write the same robot description, controllers, navigation settings, task and runtime; they differ in the simulator. See <a href="./../advanced/simulators.html">Gazebo or MuJoCo</a>.</p><h2 id="the-output-directory" tabindex="-1">The output directory <a class="header-anchor" href="#the-output-directory" aria-label="Permalink to &quot;The output directory&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>build/</span></span>
<span class="line"><span>├── robot/        robot.urdf, controllers.yaml, meshes/</span></span>
<span class="line"><span>├── world/        world.sdf and bridge.yaml, or mujoco.json</span></span>
<span class="line"><span>├── nav/          nav2.base.yaml, nav2.robot.yaml, map.pgm, map.yaml</span></span>
<span class="line"><span>├── task/         behavior_tree.xml, mission.json, evaluation.json</span></span>
<span class="line"><span>├── launch/       bringup.launch.py</span></span>
<span class="line"><span>├── runtime/      the task runner and helpers, needing only ROS 2</span></span>
<span class="line"><span>└── compile.json  what the compiler knew: facts, validation, stand-ins, sources</span></span></code></pre></div><p>Nothing in it is built or installed, and it holds no absolute path, so it can be moved or mounted anywhere. The same program, libraries and compiler version always produce the same bytes. Compiling again overwrites the files it writes and leaves every other file alone.</p><h2 id="launching" tabindex="-1">Launching <a class="header-anchor" href="#launching" aria-label="Permalink to &quot;Launching&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/launch/bringup.launch.py</span></span></code></pre></div><p>The launch brings up the simulator, the robot, its drive controller, Nav2 and the task runner, in that order, and shuts everything down when the task ends.</p><table tabindex="0"><thead><tr><th>Argument</th><th>Does</th></tr></thead><tbody><tr><td><code>headless:=false</code></td><td>Opens Gazebo&#39;s window; MuJoCo has none</td></tr><tr><td><code>navigation:=false</code></td><td>Brings up only the simulator, the robot and its controller, to drive it by hand</td></tr><tr><td><code>exit_on_task_end:=false</code></td><td>Keeps everything running after the task ends</td></tr><tr><td><code>run_dir:=DIR</code></td><td>Writes the run&#39;s results to <code>DIR</code> instead of <code>build/run</code></td></tr></tbody></table><p>To drive the base by hand, publish <code>geometry_msgs/msg/TwistStamped</code> on <code>/cmd_vel</code>. A command older than half a second stops the base.</p><h2 id="topics" tabindex="-1">Topics <a class="header-anchor" href="#topics" aria-label="Permalink to &quot;Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Carries</th></tr></thead><tbody><tr><td><code>/cmd_vel</code></td><td>Velocity commands to the base</td></tr><tr><td><code>/odom</code></td><td>The base&#39;s wheel odometry</td></tr><tr><td><code>/scan</code></td><td>The first laser, or a scan made from another range sensor</td></tr><tr><td><code>/model/&lt;robot&gt;/pose</code></td><td>The simulator&#39;s own pose of the robot, which the evaluation trusts</td></tr></tbody></table><p><a href="./../advanced/sensors.html">Sensors</a> lists every sensor&#39;s topics.</p><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><p>A run writes <code>run/task_result.json</code>, the task&#39;s own account, and <code>run/evaluation.json</code>, the three verdicts. The compiler never writes into <code>run/</code>, so compiling again keeps earlier results. <a href="./../advanced/judging-a-run.html">Judging a run</a> explains both files.</p><h2 id="stand-ins" tabindex="-1">Stand-ins <a class="header-anchor" href="#stand-ins" aria-label="Permalink to &quot;Stand-ins&quot;">​</a></h2><p>Where a simulator cannot model something as it is, the target stands in for it and says so. A mecanum wheel in Gazebo is a sphere that slides freely along its rollers&#39; axis; a lidar gets a default beam count because the library does not state one. Every stand-in is listed under <code>approximations</code> in <code>compile.json</code>, next to the component it concerns:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json.tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/compile.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> less</span></span></code></pre></div><p>What a target cannot stand in for, it refuses at compile time, and nothing is written.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>The Advanced pages go deeper, starting with <a href="./../advanced/your-own-part.html">Adding your own part</a>.</p>`,25)])])}const g=e(i,[["render",o]]);export{u as __pageData,g as default};
